window.RP_SESSION={"id":"S-26ce4493e369","messages":[{"id":"RP-0031885","time":"2026-02-06T01:54:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"엘타리온은 다시 붙은 손가락에 혈류가 도는게 느껴진다. 그리고 린의 부드러운 털을 쓰다듬는다. 그리고, 쓰다듬는다. 다시, 쓰다듬는다. 복복복복복복복... 한밤중 길드 홀의 따듯한 벽난로를 쬐며. 그저 린을 무한히 쓰다듬고 있다. 똑똑한 린, 최고의 린, 제일 좋은 개. 린을 쓰다듬는건 삶의 낙이다.","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031886","time":"2026-02-06T01:54:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"빼꼼-","characters":["P-48cca58d02b2"]},{"id":"RP-0031887","time":"2026-02-06T01:55:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"어라? 아직 안 주무시는 분이 계셨네요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031888","time":"2026-02-06T01:55:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 예쁜 언니 안녕하세요. 헤헤... \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031889","time":"2026-02-06T01:55:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"안녕하세요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031890","time":"2026-02-06T01:55:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"와! 강아지!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031891","time":"2026-02-06T01:55:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..무어..손가락은 잘 붙으신것같죠?\"\n\n\"어레, 모나씨도 계시네요\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0031892","time":"2026-02-06T01:55:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"아, 마리아씨!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031893","time":"2026-02-06T01:55:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"안주무시고 뭐하고 계셨대요..\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0031894","time":"2026-02-06T01:55:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"헤헤. 좋은 밤이에요.\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031895","time":"2026-02-06T01:56:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"아까 갑자기 누가 비명을 질러서요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031896","time":"2026-02-06T01:56:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0031897","time":"2026-02-06T01:56:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"린은 모나에게 다가가서 꼬리를 흔든다. 쓰다듬어달라는듯이...","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031898","time":"2026-02-06T01:56:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"쥐라도 나타났던 걸까요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031899","time":"2026-02-06T01:56:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그 비명, 이상하게 귀엽게 들리진 않았나요? \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031900","time":"2026-02-06T01:56:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"와아. 복슬복슬...!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031901","time":"2026-02-06T01:56:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"아하하, 그러게 말이에요\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0031902","time":"2026-02-06T01:57:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"린에게 와락 안기며 그 탐스러운 흰 털을 쓰담습니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0031903","time":"2026-02-06T01:57:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"헤헤. 할머니 털이 생각나~\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031904","time":"2026-02-06T01:57:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..풉..\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0031905","time":"2026-02-06T01:57:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"린은 꼬리를 흔들며 헥헥거립니다. 귀엽게 어리광을 부리며 부비적거리네요.","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031906","time":"2026-02-06T01:57:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"복복복","characters":["P-48cca58d02b2"]},{"id":"RP-0031907","time":"2026-02-06T01:57:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"복복복... 좋은개.","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031908","time":"2026-02-06T01:58:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"강아지는 이름이 뭐예요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031909","time":"2026-02-06T01:58:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 강아지 이름은 린이에요. 귀엽죠! \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031910","time":"2026-02-06T01:58:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"네! 귀여워요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031911","time":"2026-02-06T01:58:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"안녕, 린! 너도 우리 가족이니?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031912","time":"2026-02-06T01:58:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"복복복-","characters":["P-48cca58d02b2"]},{"id":"RP-0031913","time":"2026-02-06T01:59:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"린은 몇살이에요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031914","time":"2026-02-06T01:59:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"린은 고개를 끄덕인다.","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031915","time":"2026-02-06T02:00:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 저도 몰라요. 최소한 우리 고조할머니보다는 많아요. \"\n\n엘프 기준 고조할머니면... 도대체 몇살이지?","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031916","time":"2026-02-06T02:00:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"그 얘기를 듣자, 모나의 손이 잠시 멈칫합니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0031917","time":"2026-02-06T02:01:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"헉..! 할머니셨어요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031918","time":"2026-02-06T02:01:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"테이레시아스는 계단을 내려오던 도중 린을 발견하곤 멈칫했습니다. 그야 일반적인 개 치고는 크다고 느꼈기 때문일겁니다. 그는 긴가민가한 얼굴로 린과 일행을 가만히 지켜보기만 했습니다.","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031919","time":"2026-02-06T02:01:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 할머니도 할아버지도 아닌 것 같아요. 아무것도 안 달려있어요! \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031920","time":"2026-02-06T02:01:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"아무튼 엄청 어른이구나..!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031921","time":"2026-02-06T02:01:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그냥...털뭉치다.","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031922","time":"2026-02-06T02:01:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 어른 털뭉치! \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031923","time":"2026-02-06T02:02:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 테디베어스위스씨도 어서 와요! \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031924","time":"2026-02-06T02:02:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"안녕하세요, 린 씨! 저는 모나예요. 앞으로도 잘 부탁드려요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031925","time":"2026-02-06T02:02:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"몰래 맥주 한모금 들이키며 구경합니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-0031926","time":"2026-02-06T02:02:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"린은 엣헴. 하며 고개를 끄덕인다.","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031927","time":"2026-02-06T02:02:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 언니, 술 끊는다면서요! \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031928","time":"2026-02-06T02:02:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..어라.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0031929","time":"2026-02-06T02:02:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"....습관이 ㅎㅎ.............\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0031930","time":"2026-02-06T02:03:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"어라? 테이레시아스 씨도 아직 안 주무셨어요?\"\n복복복-","characters":["P-48cca58d02b2"]},{"id":"RP-0031931","time":"2026-02-06T02:03:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"테디베어스위스는 엘타리온의 인사를 듣고 가볍게 고개를 끄덕였습니다.\n\n\"아, 안녕하세요.\"\n\n그리고 그제서야 경계심을 늦추지 않는 표정으로 일행에게로 살금살금 다가갔습니다.","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031932","time":"2026-02-06T02:03:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 테플론코팅씨도 와서 린 쓰다듬으실래요? \"\n\n맬렁.","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031933","time":"2026-02-06T02:04:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"...이게, 이게 뭐예요? 아니, 제, 제 말은, '이거'가 아니라, 늑대예요, 개예요?\"","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031934","time":"2026-02-06T02:04:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 린은 린이에요! \"\n \n...멍!","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031935","time":"2026-02-06T02:04:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"린 씨는 엄청 어른이래요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031936","time":"2026-02-06T02:06:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"테플론코팅은 린의 멍 소리에 화들짝 놀라더니, 린을 쓰다듬지는 않고 코 앞에 손을 가져다 대기만 했습니다. (그럴 일은 없겠지만) 물릴까봐 겁을 먹은거겠죠.\n\n동시에 린과 모나를 번갈아보며 물었습니다.\n\n\"엄청 어른이라면 얼마나 어른인거죠?\"","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031937","time":"2026-02-06T02:07:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"린은 테이레시아스의 손 냄새를 킁킁 맡더니 위험하지 않다고 판단한 듯 손을 핥기 시작한다.\n\n\" 하하, 테니스스파이크씨가 마음에 들었나봐요! \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031938","time":"2026-02-06T02:09:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"모나는 진심으로 존경심 가득한 눈으로 린을 바라보며, 탐스러운 흰 털을 정성스레 쓰담습니다.\n\n\"엘타 씨의 할머니의 할머니보다 더 어른이래요! 그러면 린 씨가 길드에서 제일 어른인거죠?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031939","time":"2026-02-06T02:10:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 혹시 몰라요. 그 럴쑤인가? 하는 악마가 더 오래됐을지. \"\n\n린을 같이 쓰다듬으며.","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031940","time":"2026-02-06T02:10:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"헉...! 더 어른이 계셨구나...!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031941","time":"2026-02-06T02:11:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 아마도 그런 것 같아요. 그 소문이 사실이라면 그 악마는 수천살이 넘지 않았을까요?  \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031942","time":"2026-02-06T02:12:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"테니스 스파이크는 린의 혀가 닫는 감각에 온 몸의 털이 삐죽 솟는 것을 느꼈습니다. 그는 린에게 손을 대지도, 손을 내빼지도 못한 채 어색하게 가만히 서 있기만 했습니다.\n\n\"ㅇ엘프 기준으로 생각하면···.\"\n\n테이레시아스는 계산을 포기했지만, 그게 대강 어느정도일지는 짐작할 수 있었습니다.","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031943","time":"2026-02-06T02:12:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"으와아아...! 그러면 옛날 이야기도 무지무지 많이 알고 있겠어요! 그 얘기들을 다 들으려면, 대체 며칠 밤을 들어야 하는 걸까요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031944","time":"2026-02-06T02:13:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 아마 아무리 축약해도 제대로 배우려면 몇 년은 걸릴 것 같아요. 말 그대로 역사니까요! \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031945","time":"2026-02-06T02:14:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 테이블리스트씨 괜찮아요? \"\n\n린은 테이레시아의의 품으로 안겨들어서는 안심시키려고 해준다.","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031946","time":"2026-02-06T02:18:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"테이블리스트는 품으로 들어오는 린을 보고는 한숨을 내쉽니다. 린이 위협적인 대상은 아니라는 걸 이해한 것도 있었지만, 무엇보다도 수단에 털이 묻는 게 미치도록 신경쓰였습니다.\n\n\"ㄱ, 가, 가만히···. 가만히 있어.\"","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031947","time":"2026-02-06T02:19:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"테이레시아스 씨도 만져봐요! 무지 부드러운 털이에요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031948","time":"2026-02-06T02:19:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"복실복실한 털덩어리가 테이레시아스에게 마구 어리광을 부리며 안겨든다. 꼬리도 흔들면서...","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031949","time":"2026-02-06T02:20:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"이런 털은 좀 처럼 없어요! 정말이에요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031950","time":"2026-02-06T02:20:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"그는 분위기에 떠밀려 마지못해 털을 쓰다듬었습니다.\n\n역방향으로!;\n\n동물을 다루는 데엔 아주 미숙하네요.","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031951","time":"2026-02-06T02:20:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"앗..!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031952","time":"2026-02-06T02:21:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"엘타리온은 테이레시아스의 손을 깨문다. 오타가 아니다. 엘타리온이 깨문다. 그러곤 놓아주더니 소리친자.\n\n\" 털은 정방향으로 쓰다듬어야 해요! \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0031953","time":"2026-02-06T02:22:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"맞아요! 친절한 릴리 할머니도 그건 못 참으셨는 걸요.\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031954","time":"2026-02-06T02:25:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"테이레시아스는 엘타리온이 그의 손을 물고 놓아주자, 벙찐 표정으로 그녀를 응시했습니다. 왜 엘타리온이 그를 깨물죠? 왜 개 말고 사람이요?\n\n◉-◉?;;\n\n그는 그러더니 린을 도로 쓰다듬기 시작했습니다. 쓰다듬는다기보다도 닦아낸다는 표현이 맞을지도 모르겠지만요. 적어도 이번엔 정방향입니다.","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031955","time":"2026-02-06T02:25:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"좋아요! 그거예요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031956","time":"2026-02-06T02:27:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"어때요? 정말 감촉이 좋죠?\"\n\n모나도 그 옆에 붙어 린의 털을 복복복 쓰다듬습니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0031957","time":"2026-02-06T02:28:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"그런데 테이레시아스 씨는 원래 이 시간까지 안 주무세요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031958","time":"2026-02-06T02:28:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"저는 갑자기 비명을 들려서, 놀라서 깼지 뭐예요? 그것도 두 번이나!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031959","time":"2026-02-06T02:28:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"으음, 그,그게요, 제가 원체 잠을 잘 못 자서 말이죠.\"","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031960","time":"2026-02-06T02:29:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"앗..! 그러셨구나.\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031961","time":"2026-02-06T02:31:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"ㅂ비명은, 비명에 대해서 설명을 하자면, 잘린 손가락을 봐버려서···.\"\n\n그는 그렇게 말하더니 자연스럽게 시선을 돌렸습니다.","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031962","time":"2026-02-06T02:32:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"에? 잘린 손가락이요? 누가 다치셨어요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031963","time":"2026-02-06T02:32:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"그래도 길드엔 훌륭한 사제님들이 계시니, 금방 나았겠죠?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031964","time":"2026-02-06T02:34:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"그-그럼요, 잘린 게 손가락이라서 다행이라고 생각해요.\"\n\n\"···아- 그리고 저만 지른 건 아니에요, 정말로요.\"\n\n왜 갑자기 책임을 분산하려 할까요? 비명을 지르는 건 그다지 큰 잘못도 아닌데요.","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031965","time":"2026-02-06T02:36:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"그 얘기에 고개를 크게 끄덕이며, 잠을 깨운 소란에 대해 금방 수긍합니다.\n\n\"음음. 확실히 잘린 손가락이면 비명을 지를만해요. 쥐가 튀어나온 게 아니었구나아.\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031966","time":"2026-02-06T02:37:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"그러면 무척 깜짝 놀라서 더 잠이 안오시겠어요.\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031967","time":"2026-02-06T02:37:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"저는 잠이 안 오는 날이면 자기 전에 따뜻한 캐모마일차를 마셔요. 그러면 마음이 편해지거든요! 이건 릴리 할머니께 배운 비법이에요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031968","time":"2026-02-06T02:38:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"복복복-","characters":["P-48cca58d02b2"]},{"id":"RP-0031969","time":"2026-02-06T02:39:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"린의 새하얗고 복슬복슬한 털에서 자신을 키워준 할머니가 떠오르는지, 더욱 열심히 쓰담습니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0031970","time":"2026-02-06T02:40:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"캐모마일 차를 마시면- 잠이, 잠이 잘 오는건가요ㅡ?\"","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031971","time":"2026-02-06T02:41:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"마음을 안정? 진정? 아무튼 불안한 생각이 들지 않게 해준대요.\"\n\n그녀에겐 다소 어려운 단어인지, 정확한 효능을 떠올리진 못하지만. 암튼 그렇다고 합니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0031972","time":"2026-02-06T02:42:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"아, 아직 찻잎이 남아 있는 게 있을텐데. 테이레시아스 씨도 마셔보실래요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031973","time":"2026-02-06T02:43:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"효과는 못 보더라도. 저는 그냥 향이 좋아서 마시기도 하거든요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031974","time":"2026-02-06T02:43:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"불안한 생각이 들지 않게 해준다!\n\n\"조,좋아요, 그럴게요.\"","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031975","time":"2026-02-06T02:45:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"그러면 잠깐만 기다려 주세요! 금방 찾아 올 게요!\"\n\n모나는 물주전자를 난로 위에 올려놓은 뒤에, 찻잎을 찾으로 그녀의 방으로 총총총 올라갑니다.\n\n그리고...","characters":["P-48cca58d02b2"]},{"id":"RP-0031976","time":"2026-02-06T02:45:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-48cca58d02b2"]},{"id":"RP-0031977","time":"2026-02-06T02:45:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 2 = 2\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-0031978","time":"2026-02-06T02:46:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"뭔가 파들파들 떨면서 휘청거리는 걸음으로 다시 내려오네요.","characters":["P-48cca58d02b2"]},{"id":"RP-0031979","time":"2026-02-06T02:46:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"쏘...쏟았어요....\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031980","time":"2026-02-06T02:46:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"모무룩-","characters":["P-48cca58d02b2"]},{"id":"RP-0031981","time":"2026-02-06T02:47:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"왠지 그녀의 뿔 마저 축 쳐진것 처럼 보입니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0031982","time":"2026-02-06T02:49:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"한숨을 푹 내쉽니다.\n\n\"ㅇ,어쩔수 없죠.\"","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031983","time":"2026-02-06T02:49:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"!의지","characters":["P-48cca58d02b2"]},{"id":"RP-0031984","time":"2026-02-06T02:49:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'모나 델핀'의 의지 판정 :\n[2] + [1] = [3]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-0031985","time":"2026-02-06T02:50:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"뿔이 강아지 귀 마냥 축 처진 것 처럼 보입니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0031986","time":"2026-02-06T02:50:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"죄송해요오... 다음에는 꼬옥....\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031987","time":"2026-02-06T02:50:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"따뜻한 물이라도... 마실래요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031988","time":"2026-02-06T02:52:00+09:00","room":"RP","name":"테이레시아스","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"원래 뿔이 처지기도 하나, 하고 생각합니다.\n\n\"따,따뜻한 물이라면 많이 마셔봤는데요, ㄱ그중에서 효과가 있던 적은 한 번도···.\"","characters":["P-ca9ea162ed1b"]},{"id":"RP-0031989","time":"2026-02-06T02:53:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"그..그렇죠?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0031990","time":"2026-02-06T02:53:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"그렇게 캐모마일의 숙면 효능은 미스테리로 남은 채. 잠깐의 소란이 만들어 준 심야의 티(제로)타임은 허무하게 지나갔습니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0031991","time":"2026-02-06T02:54:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-48cca58d02b2"]},{"id":"RP-0031992","time":"2026-02-06T02:54:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
